ruleToc.chapterList:
-<js>
var id = @get:{id};
var taga = new String(java.getString("class.cartoon_catalog@tag.li@tag.h6@text&&class.cartoon_catalog@tag.li@tag.a@href",false)).split(/\n/);
var len = taga.length/2;
var list = [];
for(var i = 0; i < len; i++){
    list.push({text : taga[i], href: taga[i+len]});
}
var page = 2;
var json;
while(page>1){
    json = JSON.parse(java.postForm("https://m.manmanapp.com/works/comic-list-ajax.html","id="+id+"&sort=0&page="+page));
    if(json.code == 0) break;
    json.data.forEach(function(data){
        list.push({text : data.title, href: "https://m.manmanapp.com/comic/detail-"+data.id+".html"});
    });
    page++;
}
list
</js>

